class Submission(BaseModel):
    code: str
    problem_id: str
    problem_desc: str

@app.get("/api/problems")
def get_problems():
    return PROBLEMS_DB

@app.post("/api/run")
def run_code(submission: Submission):
    return execute_python_code(submission.code, "")

@app.post("/api/submit")
def submit_code(submission: Submission):
    problem = next((p for p in PROBLEMS_DB if p["id"] == submission.problem_id), None)
    if not problem:
        return {"status": "Error", "results": [], "message": "Problem not found"}

    results = []
    all_passed = True

    for idx, tc in enumerate(problem["test_cases"], 1):
        test_script = f"assert {tc['eval']}"
        res = execute_python_code(submission.code, test_script)
        passed = (res["status"] == "Success")
        if not passed:
            all_passed = False

        results.append({
            "test_case": idx,
            "input": tc["input"],
            "expected": tc["expected"],
            "passed": passed,
            "error": res["output"] if not passed else None
        })

    return {
        "status": "Accepted 🎉" if all_passed else "Wrong Answer ❌",
        "all_passed": all_passed,
        "results": results
    }